#!/usr/bin/env python3
"""Snapshot of static/js/topology-activity.js — who's to blame when the board paints a route.

This module is the birthplace of the "absence drawn as normal" defect class,
and of four attribution fixes: a dying cell isn't blamed on the agent
(948ad8d), a client dropout is yellow, not red (7baefad), a route
distinguishes assigned/confirmed/unverified (ea9baf0), a spike badge from
three errors an hour (f7cf791). VALUES are pinned: an incident's kind and its
reason, health ("failed" only for failed/upstream_timeout — upstream_disconnected
and blocked give "degraded", as-is), four sources of proxy activity in
priority order, the "?" status (not an incident, but painted as an error on
the recent branch — as-is), the 30s/120s/59.5s/3-errors thresholds, timeout
priority (provider > agent defaults > 3600), a route row's three-way state.

Pins live as data in PINS: (id, setup, expression, expected JSON, message).
Each pin runs in its own try/catch block: an exception becomes the value
{"__threw": "..."}, never silence. Time is frozen (Date.now = 1700000100s).
The module is loaded FOR REAL together with
state/constants/i18n/utils/model-meta/topology-proxies/polling; the
remaining neighbors are stubs (_js_harness.mjs).

Run: python3 scripts/test_js_topology_activity.py
"""
import json
import os
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(Path(__file__).resolve().parent))
sys.path.insert(0, str(ROOT))
from _node import find_node, node_search_paths, probe_args  # noqa: E402
from _contract import Contract  # noqa: E402

# The questions a Model card link can ask, from the rule that names them
# (rust/crates/admin/tests/contract.rs pins the rule): the page's tooltip table
# must cover every one, so a new question without a tooltip turns a pin red.
WINDOW_KINDS = Contract.table("controller")["windowKinds"]

STUBS = ("topology-render,topology-nodes,topology-modals,cables,routers,charts,remote-cells,cloud,history,dialogs,"
         "llama-edit,form,favorites,config-locator,system-panels,onboarding,topology-dnd,canvas,"
         "command-preview,memory,usage-stats,dialog-llamas,models-page,system-page,onboarding-tours")

PREAMBLE = r"""
import "./_js_globals.mjs";
import { pathToFileURL } from "node:url";
const st = await import(pathToFileURL(process.env.JS_ROOT + "/state.js").href);
st.setState({ config: {} });
st.setTopology({ proxies: [], clients: [], routers: [], assignments: {} });
Date.now = () => 1_700_000_100_000;
const m = await import(pathToFileURL(process.env.JS_ROOT + "/topology-activity.js").href);
const ui = st.ui;
const reset = () => { st.setState({ config: {} }); st.setTopology({ proxies: [], clients: [], routers: [], assignments: {} });
  ui.latestSystemMonitor = null; ui.routeErrHour = null; };
const norm = (s) => String(s).replace(/\s+/g, " ").trim();
// A cell's way in since 2026-11-07 (Papyrus caravan-scout-port-lease): its machine's model, of which it is a copy. cellTop(): two
// machines, one model name on each (qwen): h1 runs two copies of it (c1, c2), h2 one (c3); h1's gemma (c5) has an output that names no
// queue; c22011 is a cell no model lists. cellMon(agents): the monitor's rows of requests, by the client they came from.
const cellTop = (extra = {}) => ({ proxies: [], clients: [], assignments: {}, routers: [{ id: "router:default", outputs: [
    { id: "mm:aaa", upstreamType: "machine", hostId: "h1", upstreamModel: "qwen", upstreamHost: "10.0.0.5", upstreamPort: 8092, slotGroup: "10.0.0.5:8092/qwen" },
    { id: "mm:bbb", upstreamType: "machine", hostId: "h2", upstreamModel: "qwen", upstreamHost: "10.0.0.6", upstreamPort: 8092, slotGroup: "10.0.0.6:8092/qwen" },
    { id: "mm:ccc", upstreamType: "machine", hostId: "h1", upstreamModel: "gemma", upstreamHost: "10.0.0.5", upstreamPort: 8092 } ] }],
  nodes: [
    { id: "h1", servers: [{ cellId: "c1", port: 22011, genTps: 41.7 }, { cellId: "c2", port: 22012, genTps: 9 }, { cellId: "c22011", port: null }, { cellId: "c5", port: null }],
      entryModels: [{ id: "qwen", state: "running", copies: [{ id: "c1", port: 22011, state: "running" }, { id: "c2", port: 22012, state: "running" }] },
                    { id: "gemma", state: "stopped", copies: [{ id: "c5", port: null, state: "stopped" }] }] },
    { id: "h2", servers: [{ cellId: "c3", port: 22011, genTps: 12.5 }], entryModels: [{ id: "qwen", state: "running", copies: [{ id: "c3", port: 22011, state: "running" }] }] }],
  ...extra });
const cellMon = (agents) => { ui.latestSystemMonitor = { latest: { agentProxies: { agents } } }; };
const run = (extra = {}) => ({ phase: "running", routedOutputId: "mm:aaa", upstreamType: "machine", upstream: "10.0.0.5:8092/qwen", client: "x", startedAt: 1700000090, ...extra });
const ended = (extra = {}) => ({ status: 200, routedOutputId: "mm:aaa", upstreamType: "machine", upstream: "10.0.0.5:8092/qwen", client: "x", startedAt: 1700000040, finishedAt: 1700000050, durationMs: 10000, ...extra });
const out = {};
"""

