     'await (async () => { const en = (await import(pathToFileURL(process.env.JS_ROOT + "/i18n/en.js").href)).default; const h = m.routeWaitChipHtml({id:"c1"},{id:"a1"},"primary",{role:"primary",proxyId:"skynet:proxy:23001"}); st.topology.routers[0].graph.inputs["skynet:proxy:23001"] = {clientTimeoutSeconds: 600}; const own = m.routeWaitChipHtml({id:"c1"},{id:"a1"},"primary",{role:"primary",proxyId:"skynet:proxy:23001"}); const tip = (s) => s.match(/title="([^"]*)"/)[1].replaceAll("&#39;", "\\x27"); return [tip(h) === en.routeWaitPortTip, /synced|config/i.test(tip(h)), tip(own) === en.routeWaitOwnTip, own.includes("route-wait-chip set")]; })()',
