     'await (async () => { const en = (await import(pathToFileURL(process.env.JS_ROOT + "/i18n/en.js").href)).default; const fill = (key, vars) => Object.entries(vars).reduce((text, [k, v]) => text.split("{" + k + "}").join(v), en[key]); const h = m.routeLatencyHtml({ routeId: "p2", range: "24h", requests: 57, prepMs: { n: 57, p50: 3.1, p90: 7.4 }, connectMs: { n: 57, p50: 0, p90: 48.2 }, headersMs: { n: 57, p50: 1800, p90: 4000 }, firstChunkMs: { n: 57, p50: 1912, p90: 4200 }, cpuMs: { n: 57, p50: 11.6, p90: 25 }, connReused: { n: 49, reused: 40 } }); const rows = [...h.matchAll(/data-t-id="(\\w+)" title="([^"]*)"><span>([^<]*)<\\/span><span>([^<]*)<\\/span>/g)].map((x) => [x[1], x[3], x[4]]); return [/data-t-state="ready"/.test(h), h.includes(fill("routeLatencyRequests", { count: "57" })), rows, rows.map((r) => r[1].replace(/&#39;/g, "\x27")).join("|") === [en.routeLatencyPrep, en.routeLatencyConnect, en.routeLatencyCpu, en.routeLatencyModel].join("|")]; })()',
